import{_ as e,c as i,o as t,a2 as s}from"./chunks/framework.DWk9bKZf.js";const a=JSON.parse('{"title":"Project Overview - Introduction","description":"","frontmatter":{"layout":"doc","title":"Project Overview - Introduction"},"headers":[],"relativePath":"docs/quicklinker-zeroRPM/project-overview/introduction.md","filePath":"docs/quicklinker-zeroRPM/project-overview/introduction.md","lastUpdated":1741723016000}');const o=e({name:"docs/quicklinker-zeroRPM/project-overview/introduction.md"},[["render",function(e,a,o,r,n,l){return t(),i("div",null,a[0]||(a[0]=[s('<h1 id="project-overview-introduction" tabindex="-1">Project Overview: Introduction <a class="header-anchor" href="#project-overview-introduction" aria-label="Permalink to &quot;Project Overview: Introduction&quot;">​</a></h1><h2 id="what-is-quicklinker-zerorpm" tabindex="-1">What is QuickLinker-ZeroRPM? <a class="header-anchor" href="#what-is-quicklinker-zerorpm" aria-label="Permalink to &quot;What is QuickLinker-ZeroRPM?&quot;">​</a></h2><p>QuickLinker-ZeroRPM is a URL shortener designed to push the boundaries of cost efficiency and scalability, targeting 100,000 requests per minute (RPM) with zero infrastructure costs. Built with Node.js, Express, SQLite, and Redis, it’s hosted on Oracle’s Always Free Tier (4 Arm cores, 24 GB RAM). The project evolves through three phases—minimum viable scaling, analytics integration, and resilience engineering—each testing the limits of lightweight technologies in a production-like setting.</p><p>This isn’t just about shortening URLs; it’s a hands-on exploration of how far a single-node setup can scale, leveraging SQLite’s simplicity and Redis’s caching power, all while keeping costs at $0/month. It’s a learning journey for system engineers, challenging conventional database choices and offering practical insights into cost-performance trade-offs.</p><h2 id="core-goals" tabindex="-1">Core Goals <a class="header-anchor" href="#core-goals" aria-label="Permalink to &quot;Core Goals&quot;">​</a></h2><p>QuickLinker-ZeroRPM is driven by four key objectives:</p><ul><li><strong>Cost Efficiency</strong>: Achieve $0/month infrastructure costs by using SQLite on Oracle’s free Arm-based VMs, minimizing resource overhead compared to server-based databases like PostgreSQL or MongoDB’s replica sets.</li><li><strong>Scalability</strong>: Handle 100,000+ RPM through optimized caching (Redis) and SQLite tuning, reducing database load to a manageable level (e.g., ~33 operations/second with 99% cache hits).</li><li><strong>Reliability</strong>: Ensure 99.9% uptime with replication via LiteFS and chaos testing using Chaos Mesh, enhancing SQLite’s single-node resilience.</li><li><strong>Learning Focus</strong>: Deliver a case study on scaling SQLite for production workloads, exploring cost vs. complexity, and preparing engineers for enterprise challenges.</li></ul><p>These goals shape every decision, from database selection to deployment strategy.</p><h2 id="why-sqlite-over-postgresql-and-mongodb" tabindex="-1">Why SQLite Over PostgreSQL and MongoDB? <a class="header-anchor" href="#why-sqlite-over-postgresql-and-mongodb" aria-label="Permalink to &quot;Why SQLite Over PostgreSQL and MongoDB?&quot;">​</a></h2><p>The choice of database is central to QuickLinker-ZeroRPM’s design. Here’s how SQLite emerged as the star, with PostgreSQL as a stepping stone and MongoDB ruled out:</p><h3 id="initial-choice-postgresql" tabindex="-1">Initial Choice: PostgreSQL <a class="header-anchor" href="#initial-choice-postgresql" aria-label="Permalink to &quot;Initial Choice: PostgreSQL&quot;">​</a></h3><ul><li><strong>ACID Compliance</strong>: URL shorteners demand strong consistency—duplicate short codes or misdirected URLs are unacceptable. PostgreSQL’s robust transaction support ensures data integrity for Phase 1’s 100 req/s target.</li><li><strong>Structured Simplicity</strong>: The schema is straightforward: <code>short_code → original_url</code>. PostgreSQL’s relational model fits perfectly, avoiding the overhead of MongoDB’s flexible documents.</li><li><strong>Vertical Scaling</strong>: Phase 1 focuses on a single node, where PostgreSQL excels with connection pooling and indexing.</li></ul><h3 id="pivot-to-sqlite" tabindex="-1">Pivot to SQLite <a class="header-anchor" href="#pivot-to-sqlite" aria-label="Permalink to &quot;Pivot to SQLite&quot;">​</a></h3><ul><li><strong>Cost Efficiency</strong>: SQLite is embedded, requiring no separate server process—just a file on disk. This slashes resource needs, aligning with the $0 cost goal on a free VM. PostgreSQL, while efficient, demands more setup and memory, and MongoDB’s 3-node high-availability setup is cost-prohibitive.</li><li><strong>Migration Ease</strong>: Moving from PostgreSQL to SQLite is seamless due to shared SQL syntax, unlike MongoDB’s document model, which would require a full data layer rewrite.</li><li><strong>Performance with Tuning</strong>: Research shows SQLite can handle 80,000 inserts/second and 100,000 SELECTs/second with optimizations like Write-Ahead Logging (WAL) and synchronous normal mode (<a href="https://phiresky.github.io/blog/2020/sqlite-performance-tuning/" target="_blank" rel="noreferrer">SQLite Performance Tuning</a>). With Redis caching 99% of reads, the database sees only ~1,990 operations/minute (990 reads, 1,000 writes), well within SQLite’s tuned capacity.</li></ul><h3 id="why-not-mongodb" tabindex="-1">Why Not MongoDB? <a class="header-anchor" href="#why-not-mongodb" aria-label="Permalink to &quot;Why Not MongoDB?&quot;">​</a></h3><ul><li><strong>Read-Heavy Myth</strong>: MongoDB shines for read-heavy caching, but Redis already offloads 99% of redirects. The primary database’s role shifts to reliable writes, where MongoDB’s eventual consistency risks duplicates (e.g., two threads picking the same <code>short_code</code> before uniqueness is enforced).</li><li><strong>Cost Overhead</strong>: High availability requires a 3-node replica set, costing $15+/month in cloud resources vs. SQLite’s $0 on a single node. Even PostgreSQL can scale later with cheaper read replicas.</li><li><strong>Complexity</strong>: MongoDB’s document flexibility adds unnecessary overhead for a simple key-value use case, complicating the shift to SQLite.</li></ul><p>SQLite, enhanced by LiteFS for replication, balances cost, simplicity, and performance for this project’s unique constraints.</p><h2 id="initial-research-insights" tabindex="-1">Initial Research Insights <a class="header-anchor" href="#initial-research-insights" aria-label="Permalink to &quot;Initial Research Insights&quot;">​</a></h2><ul><li><strong>Workload Breakdown</strong>: At 100,000 RPM, assuming 1% writes (new URLs) and 99% reads (redirects), with 99% of reads cached by Redis, the database handles ~1,990 operations/minute (~33/second). Bit.ly’s 33M clicks/day (~23,000 RPM) suggests low write loads (~230 new URLs/minute), supporting this model.</li><li><strong>SQLite Feasibility</strong>: Benchmarks indicate SQLite can manage 80,000 inserts/second and 100,000 SELECTs/second with tuning (<a href="https://news.ycombinator.com/item?id=35547819" target="_blank" rel="noreferrer">Hacker News Discussion</a>), far exceeding Phase 1’s needs.</li><li><strong>Oracle Free Tier Fit</strong>: The Arm-based VM (4 cores, 24 GB RAM) offers 4 Gbps bandwidth, easily supporting the estimated 13.33 Mbps for 100,000 RPM at 1 KB/request (<a href="https://www.oracle.com/in/cloud/free/faq/" target="_blank" rel="noreferrer">Oracle Free Tier FAQ</a>).</li></ul><p>These findings validate Phase 1’s approach, setting the stage for deeper technical exploration.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>This project unfolds in phases:</p><ul><li><strong><a href="./../technical-architecture/phase-1/">Phase 1: Minimum Viable Scaling</a></strong>: Establish the core with PostgreSQL, then SQLite, targeting 100 req/s.</li><li><strong><a href="./../technical-architecture/phase-2/">Phase 2: Analytics Pipeline</a></strong>: Integrate Kafka and TimescaleDB for insights.</li><li><strong><a href="./../technical-architecture/phase-3/">Phase 3: Resilience Engineering</a></strong>: Enhance uptime with LiteFS and chaos testing.</li></ul><p>Continue to <a href="./../technical-architecture/phase-1/">Technical Architecture</a> for implementation details.</p><hr><p><em>Last Updated: March 11, 2025</em></p>',26)]))}]]);export{a as __pageData,o as default};
